"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[258],{5458(e,o,i){i.r(o),i.d(o,{assets:()=>l,contentTitle:()=>s,default:()=>p,frontMatter:()=>a,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"conduct","title":"VI. EMPLOYEE CONDUCT","description":"ABSENTEEISM AND TARDINESS","source":"@site/docs/06-conduct.md","sourceDirName":".","slug":"/conduct","permalink":"/pps-erp-sdd/conduct","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/06-conduct.md","tags":[],"version":"current","sidebarPosition":6,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"V. GROUP AND HEALTH RELATED BENEFITS","permalink":"/pps-erp-sdd/health"},"next":{"title":"VII. SAFETY & WORK AREA POLICY","permalink":"/pps-erp-sdd/safety"}}');var n=i(4848),r=i(8453);const a={},s="VI. EMPLOYEE CONDUCT",l={},c=[{value:"ABSENTEEISM AND TARDINESS",id:"absenteeism-and-tardiness",level:2},{value:"GUIDELINES FOR APPROPRIATE CONDUCT",id:"guidelines-for-appropriate-conduct",level:2},{value:"SAFE WORKPLACE POLICY",id:"safe-workplace-policy",level:2},{value:"DRUG FREE WORKPLACE POLICY",id:"drug-free-workplace-policy",level:2}];function d(e){const o={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(o.header,{children:(0,n.jsx)(o.h1,{id:"vi-employee-conduct",children:"VI. EMPLOYEE CONDUCT"})}),"\n",(0,n.jsx)(o.h2,{id:"absenteeism-and-tardiness",children:"ABSENTEEISM AND TARDINESS"}),"\n",(0,n.jsx)(o.p,{children:"The Company is able to secure work based upon our estimates of performance and our  history of reliability. Therefore, the Company expects all employees to assume diligent  responsibility for their attendance and promptness. Continued dependability, quality and  pride of service are factors over which each individual employee has a great deal of  influence. If you are absent and cannot perform your duties on time, or if you produce  substandard work, then we all pay the price by losing the confidence of the customer.\nThe work schedule is constructed around the maximum working hours and capabilities of  the staff. It is extremely important that you be punctual in your arrival for work at the  beginning of the work day or shift to which you are assigned. If you know that you will  be absent or late arriving for work, notify your supervisor within 1 hour of your scheduled  start time by calling our main number."}),"\n",(0,n.jsx)(o.p,{children:"If you are absent for more than three consecutive  workdays, a statement from a physician may be required before you will be permitted to  return to work. In such instances, the Company also reserves the right to require you to  submit to an examination by a physician designated by the Company at its discretion.\nUnexcused or excessive absenteeism or tardiness is grounds for disciplinary action, up to  and including termination. If you are absent for three or more consecutive business days and fail to properly report your absences, this will be considered a resignation of your  position and you will be terminated for abandonment of your job."}),"\n",(0,n.jsx)(o.h2,{id:"guidelines-for-appropriate-conduct",children:"GUIDELINES FOR APPROPRIATE CONDUCT"}),"\n",(0,n.jsx)(o.p,{children:"As a Company team member, employees are expected to accept certain responsibilities,  follow acceptable business principles in matters of conduct, and exhibit a high degree of  integrity at all times. This not only involves sincere respect for the rights and feelings of  others, but also demands that employees refrain from any behavior that might be harmful  to themselves, co-workers, the Company, or that might be viewed unfavorably by current  or potential customers or by the public at large. Employee conduct reflects on the  Company. Employees are, consequently, encouraged to observe the highest standards of  professionalism at all times."}),"\n",(0,n.jsx)(o.p,{children:"Types of behavior and conduct that the Company considers inappropriate include, but are  not limited to, the following:"}),"\n",(0,n.jsxs)(o.ol,{children:["\n",(0,n.jsx)(o.li,{children:"Falsifying employment or other Company records;"}),"\n",(0,n.jsx)(o.li,{children:"Violating the Company's anti-harassment policy;"}),"\n",(0,n.jsx)(o.li,{children:"Soliciting or accepting gratuities from customers or clients;"}),"\n",(0,n.jsx)(o.li,{children:"Excessive absenteeism or tardiness;"}),"\n",(0,n.jsx)(o.li,{children:"Excessive, unnecessary, or unauthorized use of Company property and supplies,  particularly for personal purposes;"}),"\n",(0,n.jsx)(o.li,{children:"Reporting to work under the influence of drugs or alcohol, and the illegal  manufacture, possession, use, sale, distribution or transportation of drugs;"}),"\n",(0,n.jsx)(o.li,{children:"Bringing or using alcoholic beverages on the Company property or using alcoholic  beverages while engaged in Company business off the Company's premises, except  where authorized;"}),"\n",(0,n.jsx)(o.li,{children:"Fighting or using obscene, abusive, or threatening language or gestures; 9. Theft of property from co-workers, customers, or the Company;"}),"\n",(0,n.jsx)(o.li,{children:"Unauthorized possession of firearms on the Company premises or while on  Company business;"}),"\n",(0,n.jsx)(o.li,{children:"Disregarding safety or security regulations;"}),"\n",(0,n.jsx)(o.li,{children:"Insubordination; and"}),"\n",(0,n.jsx)(o.li,{children:"Failing to maintain the confidentiality of Company, customer, or client  information."}),"\n"]}),"\n",(0,n.jsx)(o.p,{children:"Should an employee\u2019s performance, work habits, overall attitude, conduct or demeanor  become unsatisfactory based on violations either of the above or of any other Company  policies, rules, or regulations, the employee will be subject to disciplinary action, up to  and including employment termination.\nBefore or during imposition of any discipline, employees may be given an opportunity to  relate their version of the incident or problem at issue and provide any explanation or  justification they consider relevant."}),"\n",(0,n.jsx)(o.p,{children:"Where appropriate, a policy of progressive employee discipline will be followed by  supervisors. Major elements of this policy include:"}),"\n",(0,n.jsxs)(o.ol,{children:["\n",(0,n.jsx)(o.li,{children:"VERBAL REPRIMAND. The first step in the Company's progressive disciplinary  policy is the \"verbal reprimand.\" This is a verbal warning to an employee that his  conduct is unacceptable, and that repeated or continued failure to conform his  conduct or performance to the Company standards will result in more severe  disciplinary action. Before receiving a verbal reprimand, an employee will be  counseled by his supervisor and told what improvements are necessary and expected  to correct any performance deficiencies. A record of the notice of the verbal  reprimand may be made and retained in the employee's personnel file."}),"\n",(0,n.jsx)(o.li,{children:'WRITTEN REPRIMAND. The second step is a "written reprimand." This  reprimand will describe the unacceptable conduct or performance of the employee  and specify needed changes or improvements. A copy of the written reprimand will  be retained in the employee\'s personnel file.'}),"\n",(0,n.jsx)(o.li,{children:"SUSPENSION. Suspension of the employee's employment may, at the sole  discretion of the Company, be used as a third step. The length of the suspension  will vary based upon such factors as the severity of the offense, the employee's  performance, and the employee's disciplinary record. An employee may be  suspended for repeated instances of minor misconduct, failure to conform his  conduct or performance to the standards of his position, or for a single serious  offense. A record of the suspension will be retained in the employee's personnel  file."}),"\n",(0,n.jsx)(o.li,{children:"TERMINATION. The final step in the disciplinary procedure is the termination of  the employee. If an employee fails to conform his conduct or performance to the  standards required by the Company, the Company may, in its sole discretion,  terminate the employee's employment."}),"\n"]}),"\n",(0,n.jsx)(o.p,{children:"Notwithstanding the foregoing progressive disciplinary procedure policy, the Company  reserves the right to administer discipline in such a manner as it deems appropriate to the  circumstances, and may, in its sole discretion, eliminate any or all of the steps in the  progressive discipline procedure."}),"\n",(0,n.jsx)(o.h2,{id:"safe-workplace-policy",children:"SAFE WORKPLACE POLICY"}),"\n",(0,n.jsx)(o.p,{children:"It is the intent of the Company to provide a safe workplace for employees and to provide  a comfortable and secure atmosphere for customers and others with whom we do  business. Pressure Profile Systems, Inc. have a no tolerance guideline for violent acts or  threats of violence."}),"\n",(0,n.jsx)(o.p,{children:"Pressure Profile Systems, Inc. expect all employees to conduct themselves in a non threatening, non-abusive manner at all times. No direct, conditional or veiled threat of  harm to any employee or company property will be considered acceptable behavior. Acts  of violence or intimidation of others will not be tolerated. Any employee who commits  or threatens to commit a violent act against any person while on Company premises will  be subject to immediate discharge. If an employee, while engaged in Company business  off the premises, commits or threatens to commit a violent act, that employee will be  subject to immediate discharge if the threat or violent act could adversely affect the  Company or its reputation in the community."}),"\n",(0,n.jsx)(o.p,{children:"Employees within the company share the responsibility in identification and alleviation of  threatening or violent behaviors. Any employee who is subjected to or threatened with  violence, or who is aware of another individual who has been subjected to or threatened  with violence, shall immediately report this information to their supervisor or a member  of management. Employees should not assume that any threat is not serious. If you as an  individual feel threatened and need protection, do not hesitate to report the situation to a  supervisor. Any threat reported to a supervisor should be brought to the attention of the  Pressure Profile Systems, Inc. Human Resource Department. All reports will be carefully  investigated by Human Resources, and employee confidentiality will be maintained to the  fullest extent possible."}),"\n",(0,n.jsx)(o.h2,{id:"drug-free-workplace-policy",children:"DRUG FREE WORKPLACE POLICY"}),"\n",(0,n.jsx)(o.p,{children:'The policy of Pressure Profile Systems, Inc. ("the Company") is to maintain a drug free  workplace. For the purpose of this policy, "client" is defined as the business entity to  which the employee has been assigned by the Company. The term "workplace" is defined  as Company and/or client property, any company-sponsored and/or client-sponsored  activity, or any other site for the performance of work for the Company and/or the client.  The term "drug" includes alcoholic beverages and prescription drugs, as well as illegal  inhalants and illegal drugs. Activities prohibited by this policy shall be considered  grounds for discipline, including but not limited to suspension or immediate termination  of employment, if the activities occur in the workplace as defined above. Prohibited  activities under this policy include the unauthorized use of drugs, as defined above, in the  workplace, including distribution, possession, or use of a drug or controlled substance as  defined in schedules I through V of the Controlled Substances Act, 21 U.S.C. Sec. 812,  21 C.F.R. Sec 1308, and the state and local law of the jurisdiction where the workplace is  located, including, but not by way of limitation, marijuana, opiates (e.g., heroin,  morphine), cocaine, phencyclidine (PCP), and amphetamines. However, the use of prescription drugs, when taken as directed by a duly licensed physician, shall not be a  violation of this policy.'}),"\n",(0,n.jsx)(o.p,{children:"Information regarding the availability of treatment programs, if any, such as assistance  provided by Pressure Profile Systems, Inc. health care plan coverage or drug and alcohol  abuse rehabilitation programs and the requirements for participation in drug and alcohol  abuse education and training programs, may be requested by contacting your  management."}),"\n",(0,n.jsx)(o.p,{children:"As a condition of employment, all Company employees must comply with this policy.  Any Company employee who has been convicted under any criminal drug statute for a  violation occurring in the workplace must report that conviction to the Company no later  than five days after the conviction. Within thirty days after receiving notice of the  conviction described in this policy, the Company shall impose discipline on, or require  satisfactory participation in a drug abuse assistance or rehabilitation program, by any  employee who is convicted of a violation of a criminal drug statute if the violation  occurred in the workplace."}),"\n",(0,n.jsx)(o.p,{children:"This policy is not intended to replace or otherwise alter the obligation to comply with  requirements of the U.S. Department of Transportation or any other federal, state or local  agency that regulates drug testing administration or a particular industry."})]})}function p(e={}){const{wrapper:o}={...(0,r.R)(),...e.components};return o?(0,n.jsx)(o,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},8453(e,o,i){i.d(o,{R:()=>a,x:()=>s});var t=i(6540);const n={},r=t.createContext(n);function a(e){const o=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function s(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:a(e.components),t.createElement(r.Provider,{value:o},e.children)}}}]);